func TestStreamPackFallback(t *testing.T) {
	dec, err := zstd.NewReader(nil)
	if err != nil {
		panic(dec)
	}
	defer dec.Close()

	test := func(t *testing.T, failLoad bool) {
		key := testKey(t)
		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()

		plaintext := rtest.Random(800, 42)
		blobID := restic.Hash(plaintext)
		blobs := pack.Blobs{
			{
				Length: uint(crypto.CiphertextLength(len(plaintext))),
				Offset: 0,
				BlobHandle: restic.BlobHandle{
					ID:   blobID,
					Type: restic.DataBlob,
				},
			},
		}

		var loadPack backendLoadFn
		if failLoad {
			loadPack = func(ctx context.Context, h backend.Handle, length int, offset int64, fn func(rd io.Reader) error) error {
				return errors.New("load error")
			}
		} else {
			loadPack = func(ctx context.Context, h backend.Handle, length int, offset int64, fn func(rd io.Reader) error) error {
				// just return an empty array to provoke an error
				data := make([]byte, length)
				return fn(bytes.NewReader(data))
			}
		}

		loadBlob := func(ctx context.Context, bh restic.BlobHandle, buf []byte) ([]byte, error) {
			if bh.ID == blobID {
				return plaintext, nil
			}
			return nil, errors.New("unknown blob")
		}

		blobOK := false
		handleBlob := func(blob restic.BlobHandle, buf []byte, err error) error {
			rtest.OK(t, err)
			rtest.Equals(t, blobID, blob.ID)
			rtest.Equals(t, plaintext, buf)
			blobOK = true
			return err
		}

		err := streamPack(ctx, loadPack, loadBlob, dec, &key, restic.ID{}, blobs, handleBlob)
		rtest.OK(t, err)
		rtest.Assert(t, blobOK, "blob failed to load")
	}

	t.Run("corrupted blob", func(t *testing.T) {
		test(t, false)
	})

	// test fallback for failed pack loading
	t.Run("failed load", func(t *testing.T) {
		test(t, true)
	})
}

// A key file is just JSON in the repository, so its "data" field can be any
// length an attacker with write access to the backend picks. Make sure a
// short one is rejected instead of tripping a slice bounds panic.
func TestOpenKeyShortData(t *testing.T) {
	for _, data := range [][]byte{nil, {}, make([]byte, 1), make([]byte, crypto.CiphertextLength(0)-1)} {
		be := mem.New()
		repo, err := New(be, Options{})
		rtest.OK(t, err)

		key := Key{
			KDF:  "scrypt",
			N:    1024,
			R:    8,
			P:    1,
			Salt: make([]byte, 64),
			Data: data,
		}
		buf, err := json.Marshal(key)
		rtest.OK(t, err)

		id := restic.Hash(buf)
		h := backend.Handle{Type: backend.KeyFile, Name: id.String()}
		rtest.OK(t, be.Save(context.TODO(), h, backend.NewByteReader(buf, be.Hasher())))

		_, err = openKey(context.TODO(), repo, id, "geheim")
		rtest.Assert(t, err != nil, "expected an error for key data of length %d", len(data))
		rtest.Assert(t, strings.Contains(err.Error(), "too short"),
			"expected a 'too short' error, got %v", err)
	}
}

// The config file is exempt from the ID check in LoadRaw, so a truncated one
// reaches the decryption path unfiltered.
func TestLoadUnpackedShortData(t *testing.T) {
	be := mem.New()
	repo, err := New(be, Options{})
	rtest.OK(t, err)

	h := backend.Handle{Type: backend.ConfigFile, Name: restic.ID{}.String()}
	rtest.OK(t, be.Save(context.TODO(), h, backend.NewByteReader([]byte{}, be.Hasher())))

	repo.key = crypto.NewRandomKey()
	_, err = repo.LoadUnpacked(context.TODO(), restic.ConfigFile, restic.ID{})
	rtest.Assert(t, err != nil && strings.Contains(err.Error(), "too short"),
		"expected a 'too short' error, got %v", err)
}
